package com.pact.processor.annotation;

/** Selects the JSON body shape generated by {@link PactDslBodyBuilder}. */
public enum PactRootType {
    /** Generate a JSON object from supported model fields. */
    OBJECT,
    /** Generate a JSON array from the selected root field. */
    ARRAY,
    /** Generate a scalar JSON value from the selected root field. */
    VALUE
}
